import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({
  baseSystemPrompt: 'You are HAL.',
  systemPromptSuffix: 'Be precise.',
  contextConfig: {
    historyLength: 10,
    includeTimestamps: false,
    includeSystemPrompt: true,
  },
});

describe('beforeSession throwing', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const errorToThrow = new Error('Database connection failed in beforeSession');

    let caughtError: Error | undefined;
    let afterSessionRan = false;

    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw errorToThrow;
        },
        onError: async (_session, error) => {
          caughtError = error;
        },
        afterSession: async () => {
          afterSessionRan = true;
        },
      },
    });

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow(
      'Database connection failed in beforeSession'
    );

    expect(caughtError).toBe(errorToThrow);
    expect(afterSessionRan).toBe(true);
  });
});

export interface PromptBuilderConfig {
  identity: string;
  domainContext?: string;
  responseGuidelines?: string;
  toolPreamble?: string;
}

export interface PromptBuilderOptions {
  toolInstructions?: string[];
  additionalContext?: string;
}

const DEFAULT_TOOL_PREAMBLE = `When users ask questions that relate to available tools, USE THE PROVIDED TOOLS to get accurate, real-time information.

IMPORTANT:
- Always use tools for specific data rather than guessing.
- If a tool call fails, explain the error and offer alternatives.
- Combine tool results with your knowledge to provide comprehensive answers.

CLARIFICATION RULE: If you are unsure which filter to apply or how to interpret the user's request, ASK the user for clarification BEFORE calling the tool.
When a question is clear and maps directly to known filters, proceed without asking.`;

export class PromptBuilder {
  constructor(private readonly config: PromptBuilderConfig) {}

  build(options: PromptBuilderOptions = {}): string {
    const {toolInstructions, additionalContext} = options;
    const parts: string[] = [this.config.identity];

    if (this.config.domainContext) {
      parts.push(this.config.domainContext);
    }

    if (toolInstructions?.length) {
      const preamble = this.config.toolPreamble ?? DEFAULT_TOOL_PREAMBLE;
      const numbered = toolInstructions.map((instruction, i) => `${i + 1}. ${instruction}`).join('\n\n');
      parts.push(`${preamble}\n\n${numbered}`);
    }

    if (this.config.responseGuidelines) {
      parts.push(`Response Guidelines:\n${this.config.responseGuidelines}`);
    }

    if (additionalContext) {
      parts.push(`Additional Context:\n${additionalContext}`);
    }

    return parts.join('\n\n');
  }
}

